from flask import Flask
app = Flask(__name__)
@app.route('/')
def home():
 return """
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mi Negocio 5.0</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"></head>
<body class="bg-[#FFF8F0] min-h-screen"><div class="max-w-md mx-auto pb-[90px]">
<div class="bg-white p-3 flex justify-between items-center sticky top-0 z-20 shadow-sm"><h1 class="font-black">Mi Negocio</h1><button onclick="tab('config')" class="text-[10px] bg-gray-100 px-3 py-1 rounded-full">Config</button></div>

<!-- CREAR -->
<div id="p-costos" class="p-3">
<div class="bg-white rounded-[24px] p-4 shadow-sm">
<div id="catBotones" class="flex flex-wrap gap-2 mb-3"></div>
<input id="nombre" placeholder="Nombre producto" class="w-full border-2 p-3 rounded-xl font-bold text-sm">
<textarea id="descripcion" placeholder="Descripción" class="w-full border p-2 rounded-xl text-[11px] mt-2 h-12"></textarea>
<input id="prodImg" type="file" accept="image/*" class="text-[11px] mt-2"><img id="prevImg" class="w-20 h-20 rounded-xl object-cover mt-2 hidden">
<div id="insumos" class="mt-3 space-y-2"></div>
<div class="flex gap-2 mt-3"><button onclick="addInsumo()" class="flex-1 text-[11px] bg-orange-100 py-2 rounded-full font-bold">+ Ingrediente</button><button onclick="addInsumoSalsa()" class="flex-1 text-[11px] bg-amber-100 py-2 rounded-full font-bold">+ Base</button></div>
<div class="mt-3 p-3 bg-gray-900 text-white rounded-xl text-[12px]">Total $<span id="costo">0</span> | Venta $<span id="venta">0</span> <input id="margen" type="number" value="100" class="w-10 text-black rounded text-center text-[11px] ml-2">% | Fijos $<span id="c-fijos">0</span></div>
<button onclick="guardar()" class="w-full mt-3 bg-black text-white py-3 rounded-xl font-black text-sm">Guardar</button>
</div><div id="listaInv" class="mt-4"></div>
</div>

<!-- CATALOGO -->
<div id="p-vender" class="p-3 hidden"><div id="filtrosCat" class="flex gap-2 overflow-auto pb-2 mb-2"></div><div id="listaVenta" class="grid grid-cols-2 gap-3"></div>
<div class="mt-6 bg-white rounded-[20px] p-4 shadow-xl border"><h3 class="font-bold text-sm">Presupuesto <span id="c-count">0</span></h3><div id="c-items" class="text-[12px] mt-2"></div><select id="selCliente" class="w-full border p-2 rounded-xl text-sm mt-3"></select><div class="flex justify-between font-black text-lg mt-3">Total $<span id="c-total">0</span></div><button onclick="enviarPresupuesto()" class="w-full mt-3 bg-green-500 text-white py-3 rounded-xl font-black text-sm">WhatsApp</button><button onclick="cobrar()" class="w-full mt-2 bg-black text-white py-2 rounded-xl text-sm">Cobrar</button></div></div>

<!-- FINANZAS NUEVA -->
<div id="p-finanzas" class="p-3 hidden">
<div class="bg-[#2D3748] rounded-[20px] p-4 text-white">
<div class="flex justify-between items-center"><h2 class="font-black">Finanzas</h2><button onclick="document.getElementById('modalGasto').classList.remove('hidden')" class="bg-[#4FD1C5] text-black w-8 h-8 rounded-lg font-black">+</button></div>
<div class="grid grid-cols-3 gap-2 mt-4 text-center">
<div class="bg-white/10 p-3 rounded-2xl"><p class="text-[9px] opacity-70">FLUJO HOY</p><p class="font-black text-sm">$<span id="f-flujoHoy">0</span></p></div>
<div class="bg-red-500/80 p-3 rounded-2xl"><p class="text-[9px]">POR PAGAR</p><p class="font-black text-sm">$<span id="f-porPagar">0</span></p></div>
<div class="bg-green-500 p-3 rounded-2xl"><p class="text-[9px]">VENCIDO</p><p class="font-black text-sm">$<span id="f-vencido">0</span></p></div>
</div>
<div class="mt-4 grid grid-cols-4 gap-2 text-[10px]">
<button onclick="filtroFin='todos';mostrarFinanzas()" id="ff-todos" class="bg-white text-black py-2 rounded-full font-bold">Todos</button>
<button onclick="filtroFin='atrasados';mostrarFinanzas()" id="ff-atrasados" class="bg-red-500 py-2 rounded-full font-bold">Atrasados</button>
<button onclick="filtroFin='porVencer';mostrarFinanzas()" id="ff-porVencer" class="bg-yellow-400 text-black py-2 rounded-full font-bold">Por vencer</button>
<button onclick="filtroFin='futuros';mostrarFinanzas()" id="ff-futuros" class="bg-white/20 py-2 rounded-full">Futuros</button>
</div>
</div>

<div class="mt-3 bg-white rounded-2xl p-3 shadow-sm">
<div class="flex justify-between"><h3 class="font-bold text-[12px]">Calendario de pagos</h3><input id="calFecha" type="date" class="text-[11px] border rounded-lg p-1" onchange="mostrarFinanzas()"></div>
<div id="f-calendario" class="mt-2"></div>
</div>

<div class="mt-3 bg-white rounded-2xl p-3 shadow-sm">
<div class="flex gap-2 mb-2"><button onclick="subFin='salidas';mostrarFinanzas()" class="text-[10px] bg-red-100 px-3 py-1 rounded-full font-bold">Salidas</button><button onclick="subFin='entradas';mostrarFinanzas()" class="text-[10px] bg-green-100 px-3 py-1 rounded-full font-bold">Entradas</button><button onclick="subFin='todos';mostrarFinanzas()" class="text-[10px] bg-gray-100 px-3 py-1 rounded-full">Todos</button></div>
<div id="f-lista"></div>
</div>

<div id="modalGasto" class="hidden fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4"><div class="bg-white w-full max-w-sm rounded-[20px] p-5">
<h3 class="font-black text-sm">Agregar Gasto / Factura</h3>
<select id="g-tipo" class="w-full border p-3 rounded-xl text-sm mt-3"><option value="salida">Salida / Gasto</option><option value="entrada">Entrada / Por cobrar</option></select>
<input id="g-concepto" placeholder="Concepto: Renta, Luz, Proveedor X" class="w-full border p-3 rounded-xl text-sm mt-2">
<input id="g-monto" type="number" placeholder="$ Monto" class="w-full border p-3 rounded-xl text-sm mt-2">
<input id="g-proveedor" placeholder="Proveedor (opcional)" class="w-full border p-3 rounded-xl text-sm mt-2">
<label class="text-[11px] font-bold mt-2 block">Fecha vencimiento:</label><input id="g-fecha" type="date" class="w-full border p-3 rounded-xl text-sm">
<div class="flex gap-2 mt-4"><button onclick="document.getElementById('modalGasto').classList.add('hidden')" class="flex-1 bg-gray-100 py-3 rounded-xl text-sm">Cancelar</button><button onclick="addFactura()" class="flex-1 bg-black text-white py-3 rounded-xl text-sm font-bold">Guardar</button></div>
</div></div>
</div>

<div id="p-clientes" class="p-3 hidden"><div class="bg-white rounded-2xl p-4 shadow-sm"><input id="cliNombre" placeholder="Nombre" class="border p-3 rounded-xl text-sm w-full mb-2"><input id="cliTel" placeholder="WhatsApp" class="border p-3 rounded-xl text-sm w-full mb-2"><input id="cliDir" placeholder="Dirección" class="border p-3 rounded-xl text-sm w-full mb-2"><button onclick="addCliente()" class="bg-black text-white w-full py-3 rounded-xl font-bold text-sm">Guardar cliente</button></div><div id="listaClientes" class="mt-3 space-y-2"></div></div>

<div id="p-config" class="p-3 hidden">
<div class="bg-white rounded-2xl p-4 shadow-sm"><h2 class="font-black text-sm">Categorías</h2><div id="listaCats" class="mt-3 space-y-2"></div><div class="flex gap-2 mt-3"><input id="newCat" placeholder="Nueva categoría" class="flex-1 border p-2.5 rounded-xl text-sm"><button onclick="addCategoria()" class="bg-black text-white px-4 rounded-xl">+</button></div></div>
<div class="bg-white rounded-2xl p-4 shadow-sm mt-4"><h2 class="font-black text-sm">Gastos fijos mensuales (para costeo)</h2><div id="gastosFijos" class="mt-3 space-y-2"></div><button onclick="addGastoFijo()" class="w-full mt-2 bg-gray-100 py-2 rounded-full text-[11px] font-bold">+ Gasto</button><input id="prodMes" type="number" value="100" class="w-full border-2 p-3 rounded-xl mt-3 font-bold" oninput="calcGastosFijos()"><div class="mt-2 bg-black text-white p-3 rounded-xl text-center font-black">$<span id="cfg-porReceta">0</span> por producto</div></div>
</div>

<div class="fixed bottom-0 left-0 right-0 bg-white border-t flex justify-around py-2 max-w-md mx-auto z-30 text-gray-300">
<button onclick="tab('costos')" id="nav-costos" class="flex flex-col items-center text-black"><i class="fa-solid fa-calculator"></i><span class="text-[8px] font-bold">Crear</span></button>
<button onclick="tab('vender')" id="nav-vender" class="flex flex-col items-center"><i class="fa-solid fa-store"></i><span class="text-[8px]">Catálogo</span></button>
<button onclick="tab('finanzas')" id="nav-finanzas" class="flex flex-col items-center"><i class="fa-solid fa-chart-line"></i><span class="text-[8px]">Finanzas</span></button>
<button onclick="tab('clientes')" id="nav-clientes" class="flex flex-col items-center"><i class="fa-solid fa-users"></i><span class="text-[8px]">Clientes</span></button>
</div></div>
<script>
let tipoActual='', carrito=[], prodImgBase='', filtroTipo='todos', filtroFin='todos', subFin='todos'; const U=['kg','g','L','ml','galon','pza','cda'];
function baseFactor(u){ if(u=='kg'||u=='L') return 1000; if(u=='galon') return 3785; return 1;}
document.getElementById('prodImg').onchange=e=>{let r=new FileReader(); r.onload=()=>{prodImgBase=r.result; document.getElementById('prevImg').src=r.result; document.getElementById('prevImg').classList.remove('hidden');}; r.readAsDataURL(e.target.files[0]);};
function getCats(){let c=JSON.parse(localStorage.getItem('categorias')||'null'); if(!c){c=[{id:'salsa',nombre:'Salsa / Base',esBase:true},{id:'platillo',nombre:'Platillo',esBase:false}]; localStorage.setItem('categorias',JSON.stringify(c));} return c;}
function saveCats(c){localStorage.setItem('categorias',JSON.stringify(c)); renderCats(); renderCatBotones();}
function renderCats(){let cats=getCats(); let h=''; cats.forEach((cat,i)=>{h+=`<div class="flex gap-2 items-center bg-gray-50 p-2 rounded-xl"><input value="${cat.nombre}" onchange="let cs=getCats(); cs[${i}].nombre=this.value; saveCats(cs);" class="flex-1 bg-transparent font-bold text-sm outline-none"><label class="text-[10px] flex items-center gap-1"><input type="checkbox" ${cat.esBase?'checked':''} onchange="let cs=getCats(); cs[${i}].esBase=this.checked; saveCats(cs);"> Base?</label><button onclick="let cs=getCats(); cs.splice(${i},1); saveCats(cs);" class="text-red-300 px-2">x</button></div>`;}); document.getElementById('listaCats').innerHTML=h;}
function renderCatBotones(){let cats=getCats(); if(!tipoActual) tipoActual=cats[0]?.id||''; let h=''; cats.forEach(cat=>{let act=cat.id==tipoActual; h+=`<button onclick="tipoActual='${cat.id}'; renderCatBotones(); calc();" class="px-4 py-2 rounded-full text-[11px] font-black border ${act?'bg-black text-white':'bg-white'}">${cat.nombre}</button>`;}); document.getElementById('catBotones').innerHTML=h;}
function addCategoria(){let n=document.getElementById('newCat').value.trim(); if(!n) return; let cats=getCats(); cats.push({id:Date.now().toString(),nombre:n,esBase:false}); document.getElementById('newCat').value=''; saveCats(cats);}
function addInsumo(d={}){let div=document.createElement('div'); div.className='bg-[#FFF8F0] p-2 rounded-xl border text-[11px]'; div.dataset.tipo='ing'; div.innerHTML=`<div class="flex justify-between"><input placeholder="Ingrediente" value="${d.n||''}" class="in-n font-bold text-sm w-full bg-transparent outline-none"><button onclick="this.parentElement.parentElement.remove();calc()" class="text-red-300">x</button></div><div class="grid grid-cols-3 gap-1 mt-1"><input type="number" value="${d.cc||''}" placeholder="Cant" class="in-cc border p-2 rounded-lg" oninput="calc()"><select class="in-uc border p-2 rounded-lg" onchange="calc()">${U.map(x=>`<option ${d.uc==x?'selected':''}>${x}</option>`).join('')}</select><input type="number" value="${d.pc||''}" placeholder="$" class="in-pc border p-2 rounded-lg" oninput="calc()"><input type="number" value="${d.cu||''}" placeholder="Uso" class="in-cu border p-2 rounded-lg" oninput="calc()"><select class="in-uu border p-2 rounded-lg" onchange="calc()">${U.map(x=>`<option ${d.uu==x?'selected':''}>${x}</option>`).join('')}</select><div class="p-2 bg-white rounded-lg text-center font-bold">$<span class="in-sub">0</span></div></div>`; document.getElementById('insumos').appendChild(div);}
function addInsumoSalsa(){let cats=getCats(); let bases=cats.filter(c=>c.esBase).map(c=>c.id); let salsas=getProd().filter(p=>bases.includes(p.tipo)); if(!salsas.length) return alert('Marca una categoría como Base'); let div=document.createElement('div'); div.className='bg-amber-50 p-2 rounded-xl border text-[11px]'; div.dataset.tipo='salsa'; div.innerHTML=`<div class="flex justify-between"><span class="font-bold">Base</span><button onclick="this.parentElement.parentElement.remove();calc()" class="text-red-300">x</button></div><div class="flex gap-1 mt-1"><select class="in-salsa border p-2 rounded-lg flex-1" onchange="calc()">${salsas.map(s=>`<option value="${s.id}" data-costo="${s.costo}">${s.nombre}</option>`).join('')}</select><input type="number" value="1" class="in-salsaCant w-16 border p-2 rounded-lg" oninput="calc()"><div class="p-2 bg-white rounded-lg font-bold">$<span class="in-sub">0</span></div></div>`; document.getElementById('insumos').appendChild(div); calc();}
addInsumo({n:'Cebolla',cc:1,uc:'kg',pc:40,cu:150,uu:'g'});
function getProd(){return JSON.parse(localStorage.getItem('productosV2')||'[]');}
function calcGastosFijos(){let total=0; document.querySelectorAll('#gastosFijos > div').forEach(r=>total+=parseFloat(r.querySelector('.gf-m').value)||0); let prodMes=parseFloat(document.getElementById('prodMes').value)||100; localStorage.setItem('prodMes',prodMes); let arr=[]; document.querySelectorAll('#gastosFijos > div').forEach(r=>arr.push({nombre:r.querySelector('.gf-n').value,monto:parseFloat(r.querySelector('.gf-m').value)||0})); localStorage.setItem('gastosFijos',JSON.stringify(arr)); let por=prodMes>0?total/prodMes:0; document.getElementById('cfg-porReceta').innerText=por.toFixed(2); document.getElementById('c-fijos').innerText=por.toFixed(2); calc();}
function calc(){let tot=0; document.querySelectorAll('#insumos > div').forEach(row=>{if(row.dataset.tipo=='salsa'){let sel=row.querySelector('.in-salsa'); let costo=parseFloat(sel.options[sel.selectedIndex].dataset.costo)||0; let cant=parseFloat(row.querySelector('.in-salsaCant').value)||0; let sub=costo*cant; row.querySelector('.in-sub').innerText=sub.toFixed(2); tot+=sub;}else{let cc=parseFloat(row.querySelector('.in-cc').value)||0, pc=parseFloat(row.querySelector('.in-pc').value)||0, cu=parseFloat(row.querySelector('.in-cu').value)||0, uc=row.querySelector('.in-uc').value, uu=row.querySelector('.in-uu').value; if(!cc||!pc||!cu){row.querySelector('.in-sub').innerText='0'; return;} let cost=(pc/(cc*baseFactor(uc)))*(cu*baseFactor(uu)); if(uc=='pza'||uu=='pza') cost=(pc/cc)*cu; row.querySelector('.in-sub').innerText=cost.toFixed(2); tot+=cost;}}); document.getElementById('c-ing').innerText=tot.toFixed(2); let gf=parseFloat(document.getElementById('c-fijos').innerText)||0; document.getElementById('costo').innerText=(tot+gf).toFixed(2); let m=parseFloat(document.getElementById('margen').value)||0; document.getElementById('venta').innerText=((tot+gf)*(1+m/100)).toFixed(2);}
document.getElementById('margen').oninput=calc;
function tab(t){['costos','vender','finanzas','clientes','config'].forEach(x=>{document.getElementById('p-'+x).classList.toggle('hidden',x!=t); let nav=document.getElementById('nav-'+x); if(nav){nav.classList.toggle('text-black',x==t);}}); if(t=='vender') mostrarVenta(); if(t=='finanzas') mostrarFinanzas(); if(t=='clientes') mostrarClientes(); if(t=='config') renderCats();}
function getMovs(){return JSON.parse(localStorage.getItem('movs')||'[]');} function getClientes(){return JSON.parse(localStorage.getItem('clientes')||'[]');} function getFacturas(){return JSON.parse(localStorage.getItem('facturas')||'[]');}
function guardar(){let nombre=document.getElementById('nombre').value.trim(); if(!nombre) return alert('Nombre'); if(!tipoActual) return alert('Categoría'); let desc=document.getElementById('descripcion').value; let costo=parseFloat(document.getElementById('costo').innerText), venta=parseFloat(document.getElementById('venta').innerText); let p=getProd(); p.push({id:Date.now(),tipo:tipoActual,nombre,descripcion:desc,costo,venta,img:prodImgBase}); localStorage.setItem('productosV2',JSON.stringify(p)); prodImgBase=''; document.getElementById('nombre').value=''; document.getElementById('descripcion').value=''; document.getElementById('prevImg').classList.add('hidden'); document.getElementById('insumos').innerHTML=''; addInsumo({}); calc(); mostrar();}
function mostrar(){let prods=getProd(); let cats=getCats(); let h=`<h2 class="font-black text-sm mt-4">Productos (${prods.length})</h2>`; prods.forEach((p,i)=>{let cat=cats.find(c=>c.id==p.tipo); h+=`<div class="bg-white p-2 rounded-xl flex gap-2 shadow-sm mt-2 items-center"><span class="text-[9px] bg-gray-100 px-2 py-1 rounded-full font-bold">${cat?cat.nombre:''}</span><img src="${p.img||''}" class="w-10 h-10 rounded object-cover bg-gray-100"><div class="flex-1"><b class="text-[12px]">${p.nombre}</b><br><span class="text-[10px]">$${p.costo.toFixed(2)} → $${p.venta.toFixed(2)}</span></div><button onclick="let pr=getProd(); pr.splice(${i},1); localStorage.setItem('productosV2',JSON.stringify(pr)); mostrar();" class="text-red-300">X</button></div>`;}); document.getElementById('listaInv').innerHTML=h; mostrarVenta();}
function mostrarVenta(){let prods=getProd(); let cats=getCats(); let filtros=document.getElementById('filtrosCat'); filtros.innerHTML=`<button onclick="filtroTipo='todos';mostrarVenta()" class="px-3 py-1 rounded-full text-[10px] ${filtroTipo=='todos'?'bg-black text-white':'bg-white border'}">Todos</button>`+cats.map(c=>`<button onclick="filtroTipo='${c.id}';mostrarVenta()" class="px-3 py-1 rounded-full text-[10px] ${filtroTipo==c.id?'bg-black text-white':'bg-white border'}">${c.nombre}</button>`).join(''); if(filtroTipo!='todos') prods=prods.filter(p=>p.tipo==filtroTipo); let h=''; prods.forEach(p=>{let cat=cats.find(c=>c.id==p.tipo); h+=`<button onclick="addCart(${p.id})" class="bg-white rounded-2xl shadow-sm border overflow-hidden text-left"><div class="relative"><img src="${p.img||'https://via.placeholder.com/200'}" class="w-full h-24 object-cover"><span class="absolute top-1 left-1 text-[8px] bg-white px-2 py-0.5 rounded-full font-bold">${cat?cat.nombre:''}</span></div><div class="p-2"><b class="text-[11px] line-clamp-1">${p.nombre}</b><p class="text-[11px] text-green-600 font-bold">$${p.venta.toFixed(2)}</p></div></button>`;}); document.getElementById('listaVenta').innerHTML=h||'<p class="text-center text-sm text-gray-400 col-span-2">Sin productos</p>'; let cli=getClientes(); document.getElementById('selCliente').innerHTML='<option value="">Cliente</option>'+cli.map(c=>`<option value="${c.id}">${c.nombre}</option>`).join('');}
function addCart(id){let p=getProd().find(x=>x.id==id); let ex=carrito.find(x=>x.id==id); if(ex) ex.qty++; else carrito.push({...p,qty:1}); renderCart();}
function renderCart(){let t=0,c=0,html=''; carrito.forEach(x=>{t+=x.venta*x.qty; c+=x.qty; html+=`<div class="flex justify-between py-1 text-[12px]"><span>${x.nombre} x${x.qty}</span><span>$${(x.venta*x.qty).toFixed(0)}</span></div>`;}); document.getElementById('c-total').innerText=t.toFixed(0); document.getElementById('c-count').innerText=c; document.getElementById('c-items').innerHTML=html||'Vacío';}
function vaciar(){carrito=[]; renderCart();}
function cobrar(){if(!carrito.length) return; let total=parseFloat(document.getElementById('c-total').innerText); let movs=getMovs(); movs.unshift({tipo:'entrada',concepto:'Venta: '+carrito.map(c=>c.nombre).join(','),monto:total,fecha:new Date().toLocaleDateString()}); localStorage.setItem('movs',JSON.stringify(movs)); vaciar(); tab('finanzas');}
function enviarPresupuesto(){if(!carrito.length) return; let texto=`*PRESUPUESTO*%0A`; carrito.forEach(p=>texto+=`• ${p.nombre} x${p.qty} $${(p.venta*p.qty).toFixed(2)}%0A`); texto+=`*TOTAL $${document.getElementById('c-total').innerText}*`; window.open('https://wa.me/?text='+texto,'_blank');}
function addCliente(){let n=document.getElementById('cliNombre').value, tel=document.getElementById('cliTel').value, dir=document.getElementById('cliDir').value; if(!n) return; let cli=getClientes(); cli.push({id:Date.now().toString(),nombre:n,tel,direccion:dir}); localStorage.setItem('clientes',JSON.stringify(cli)); mostrarClientes();}
function mostrarClientes(){let cli=getClientes(); let h=''; cli.forEach((c,i)=>h+=`<div class="bg-white p-3 rounded-xl flex justify-between shadow-sm"><div><b class="text-[12px]">${c.nombre}</b><br><span class="text-[10px]">${c.tel} ${c.direccion||''}</span></div><button onclick="let cl=getClientes(); cl.splice(${i},1); localStorage.setItem('clientes',JSON.stringify(cl)); mostrarClientes();" class="text-red-300">X</button></div>`); document.getElementById('listaClientes').innerHTML=h;}
function addFactura(){let concepto=document.getElementById('g-concepto').value.trim(), monto=parseFloat(document.getElementById('g-monto').value), fecha=document.getElementById('g-fecha').value, tipo=document.getElementById('g-tipo').value, prov=document.getElementById('g-proveedor').value; if(!concepto||!monto||!fecha) return alert('Faltan datos'); let facts=getFacturas(); facts.push({id:Date.now(),concepto,monto,fecha,fechaObj:new Date(fecha+'T00:00:00').getTime(),tipo,proveedor:prov,estado:'pendiente'}); localStorage.setItem('facturas',JSON.stringify(facts)); document.getElementById('modalGasto').classList.add('hidden'); document.getElementById('g-concepto').value=''; document.getElementById('g-monto').value=''; document.getElementById('g-proveedor').value=''; mostrarFinanzas();}
function mostrarFinanzas(){let facts=getFacturas(); let movs=getMovs(); let hoy=new Date(); hoy.setHours(0,0,0,0); let hoyTime=hoy.getTime(); let calFecha=document.getElementById('calFecha').value; let ent=0,sal=0,porPagar=0,vencido=0,flujoHoy=0; movs.forEach(m=>{if(m.tipo=='entrada') ent+=m.monto; else sal+=m.monto;}); let lista=facts.slice(); if(calFecha){let fTime=new Date(calFecha+'T00:00:00').getTime(); lista=lista.filter(f=>f.fechaObj==fTime);} if(subFin!='todos') lista=lista.filter(f=>f.tipo==subFin); if(filtroFin=='atrasados') lista=lista.filter(f=>f.fechaObj<hoyTime && f.estado=='pendiente'); if(filtroFin=='porVencer') lista=lista.filter(f=>{let diff=(f.fechaObj-hoyTime)/(1000*60*60*24); return diff>=0 && diff<=7 && f.estado=='pendiente';}); if(filtroFin=='futuros') lista=lista.filter(f=>{let diff=(f.fechaObj-hoyTime)/(1000*60*60*24); return diff>7 && f.estado=='pendiente';}); facts.forEach(f=>{if(f.estado=='pendiente' && f.tipo=='salida'){porPagar+=f.monto; if(f.fechaObj<hoyTime) vencido+=f.monto;}}); movs.forEach(m=>{let d=new Date(m.fecha); if(d.toDateString()==new Date().toDateString()){if(m.tipo=='entrada') flujoHoy+=m.monto; else flujoHoy-=m.monto;}}); document.getElementById('f-porPagar').innerText=porPagar.toFixed(0); document.getElementById('f-vencido').innerText=vencido.toFixed(0); document.getElementById('f-flujoHoy').innerText=flujoHoy.toFixed(0); let h=''; let grouped={}; lista.forEach(f=>{let key=f.fecha; if(!grouped[key]) grouped[key]=[]; grouped[key].push(f);}); Object.keys(grouped).sort().forEach(fecha=>{let diff=(new Date(fecha+'T00:00:00').getTime()-hoyTime)/(1000*60*60*24); let label=''; let color=''; if(diff<0){label='ATRASADO'; color='bg-red-500';} else if(diff==0){label='HOY'; color='bg-black';} else if(diff<=3){label='POR VENCER'; color='bg-yellow-400 text-black';} else {label='FUTURO'; color='bg-gray-200 text-gray-600';} h+=`<div class="mt-3"><div class="flex items-center gap-2"><span class="text-[10px] ${color} text-white px-2 py-0.5 rounded-full font-bold">${label}</span><span class="text-[11px] font-bold">${fecha}</span></div>`; grouped[fecha].forEach((f,i)=>{let isVenc=f.fechaObj<hoyTime && f.estado=='pendiente'; h+=`<div class="flex justify-between items-center py-2 border-b ${isVenc?'bg-red-50':''}"><div class="flex-1"><p class="text-[12px] font-bold ${isVenc?'text-red-600':''}"><i class="fa-solid ${f.tipo=='salida'?'fa-arrow-down text-red-400':'fa-arrow-up text-green-500'}"></i> ${f.concepto} ${f.proveedor?'<span class="text-[10px] text-gray-400">- '+f.proveedor+'</span>':''}</p><p class="text-[10px] text-gray-400">${f.tipo} • ${f.estado}</p></div><div class="text-right"><b class="text-[12px] ${f.tipo=='salida'?'text-red-500':'text-green-600'}">$${f.monto}</b><br><button onclick="let fs=getFacturas(); let idx=fs.findIndex(x=>x.id==${f.id}); if(fs[idx].estado=='pendiente'){fs[idx].estado='pagado'; let ms=getMovs(); ms.unshift({tipo:fs[idx].tipo,concepto:fs[idx].concepto,monto:fs[idx].monto,fecha:new Date().toLocaleDateString()}); localStorage.setItem('movs',JSON.stringify(ms));} else {fs[idx].estado='pendiente';} localStorage.setItem('facturas',JSON.stringify(fs)); mostrarFinanzas();" class="text-[10px] ${f.estado=='pagado'?'bg-green-500 text-white':'bg-black text-white'} px-2 py-0.5 rounded-full">${f.estado=='pagado'?'Pagado':'Pagar'}</button> <button onclick="let fs=getFacturas(); fs=fs.filter(x=>x.id!=${f.id}); localStorage.setItem('facturas',JSON.stringify(fs)); mostrarFinanzas();" class="text-red-300 text-[10px]">x</button></div></div>`;}); h+=`</div>`;}); if(!h) h='<p class="text-center text-[11px] text-gray-400 py-6">Sin facturas en este filtro.<br> Dale + para agregar gasto del día</p>'; document.getElementById('f-lista').innerHTML=h; let calH=''; let proximos=facts.filter(f=>f.estado=='pendiente').sort((a,b)=>a.fechaObj-b.fechaObj).slice(0,5); proximos.forEach(f=>{let diff=Math.ceil((f.fechaObj-hoyTime)/(1000*60*60*24)); let txt=diff<0?`Venció hace ${Math.abs(diff)}d`: diff==0?'Vence hoy':`En ${diff} días`; calH+=`<div class="flex justify-between text-[11px] py-1 border-b"><span>${f.concepto} • ${f.fecha}</span><span class="${diff<0?'text-red-500 font-bold':'text-gray-500'}">${txt}</span></div>`;}); document.getElementById('f-calendario').innerHTML=calH||'<p class="text-[11px] text-gray-400">Sin pendientes</p>'; document.querySelectorAll('[id^="ff-"]').forEach(b=>b.classList.remove('ring-2')); let actBtn=document.getElementById('ff-'+filtroFin); if(actBtn) actBtn.classList.add('ring-2');}
function getGF(){return JSON.parse(localStorage.getItem('gastosFijos')||'[]');} function addGastoFijo(d={}){let div=document.createElement('div'); div.className='flex gap-2'; div.innerHTML=`<input value="${d.nombre||''}" placeholder="Concepto" class="gf-n flex-1 border p-2 rounded-xl text-sm"><input type="number" value="${d.monto||''}" placeholder="$" class="gf-m w-24 border p-2 rounded-xl text-sm" oninput="calcGastosFijos()"><button onclick="this.parentElement.remove();calcGastosFijos()" class="text-red-300">x</button>`; document.getElementById('gastosFijos').appendChild(div);}
let sGF=getGF(); if(sGF.length) sGF.forEach(g=>addGastoFijo(g)); else {addGastoFijo({nombre:'Renta',monto:3000});} document.getElementById('prodMes').value=localStorage.getItem('prodMes')||100; let today=new Date().toISOString().split('T')[0]; document.getElementById('g-fecha').value=today; document.getElementById('calFecha').value=''; renderCats(); renderCatBotones(); calcGastosFijos(); calc(); mostrar(); mostrarClientes(); mostrarFinanzas();
</script></body></html>
"""
